"use client"

export type PdfTextItem = { str?: string }
export type PdfTextContent = { items: PdfTextItem[] }

export type PdfPageProxy = {
  getViewport: (options: { scale: number }) => { width: number; height: number }
  getTextContent?: () => Promise<PdfTextContent>
  render: (options: {
    canvasContext: CanvasRenderingContext2D
    viewport: { width: number; height: number }
    transform?: number[]
  }) => { promise: Promise<void>; cancel: () => void }
}

export type PdfDocumentProxy = {
  numPages: number
  getPage: (pageNumber: number) => Promise<PdfPageProxy>
}

export type PdfLoadResult = {
  task: { destroy: () => Promise<void> }
  doc: PdfDocumentProxy
}

export type PdfSource = string | { data: ArrayBuffer }

export async function loadPdfDocument(src: PdfSource): Promise<PdfLoadResult> {
  const pdfjs = await import("pdfjs-dist")
  if (!pdfjs.GlobalWorkerOptions.workerSrc && !pdfjs.GlobalWorkerOptions.workerPort) {
    pdfjs.GlobalWorkerOptions.workerSrc = new URL(
      "pdfjs-dist/build/pdf.worker.min.mjs",
      import.meta.url
    ).toString()
  }
  const source = typeof src === "string" ? { url: src } : src
  const task = pdfjs.getDocument(source)
  const doc = (await task.promise) as unknown as PdfDocumentProxy
  return { task, doc }
}

export function renderPdfPageToCanvas(input: {
  page: PdfPageProxy
  canvas: HTMLCanvasElement
  scale: number
  pixelRatio?: number
}): { promise: Promise<void>; cancel: () => void } {
  const pixelRatio = input.pixelRatio ?? (typeof window === "undefined" ? 1 : Math.max(1, window.devicePixelRatio || 1))
  const viewport = input.page.getViewport({ scale: input.scale })
  const context = input.canvas.getContext("2d")
  if (!context) {
    throw new Error("Could not create a canvas for this PDF page.")
  }
  input.canvas.width = Math.max(1, Math.floor(viewport.width * pixelRatio))
  input.canvas.height = Math.max(1, Math.floor(viewport.height * pixelRatio))
  input.canvas.style.width = `${Math.floor(viewport.width)}px`
  input.canvas.style.height = `${Math.floor(viewport.height)}px`
  const transform = pixelRatio === 1 ? undefined : [pixelRatio, 0, 0, pixelRatio, 0, 0]
  return input.page.render({ canvasContext: context, viewport, transform })
}

/**
 * Plain text of a page, for search and speech.
 *
 * This is deliberately separate from the selectable text layer below. A curl
 * sheet is mid-flight 3D-transformed and cloned outside React, so putting
 * real selectable spans on it would break selection and cost a layer per
 * page. Paged curl reading wants *findable* text; only the flat reader wants
 * *selectable* text.
 */
export async function extractPdfPageText(page: PdfPageProxy): Promise<string> {
  if (typeof page.getTextContent !== "function") return ""
  try {
    const content = await page.getTextContent()
    return content.items
      .map((item) => item.str ?? "")
      .join(" ")
      .replace(/\s+/g, " ")
      .trim()
  } catch {
    // An image-only or malformed page simply has no text.
    return ""
  }
}

/**
 * Renders a real, selectable text layer over an already-painted canvas.
 * The container must be positioned and exactly overlay the canvas box.
 */
export async function renderPdfTextLayer(input: {
  page: PdfPageProxy
  container: HTMLElement
  scale: number
}): Promise<{ cancel: () => void }> {
  if (typeof input.page.getTextContent !== "function") {
    return { cancel: () => {} }
  }
  const pdfjs = await import("pdfjs-dist")
  const viewport = input.page.getViewport({ scale: input.scale })
  const textContentSource = await input.page.getTextContent()
  const layer = new pdfjs.TextLayer({
    textContentSource: textContentSource as never,
    container: input.container,
    viewport: viewport as never,
  })
  await layer.render()
  return { cancel: () => layer.cancel() }
}

/** Intrinsic aspect ratio (height / width) of a page at scale 1. */
export function pdfPageAspectRatio(page: PdfPageProxy): number {
  const base = page.getViewport({ scale: 1 })
  if (!(base.width > 0) || !(base.height > 0)) return Math.SQRT2
  return base.height / base.width
}

function canvasToObjectUrl(canvas: HTMLCanvasElement): Promise<string> {
  return new Promise((resolve) => {
    // Blob URLs keep the bitmap out of the JS heap. A base64 data URL of the
    // same page is ~33% larger and is copied again by every DOM clone the
    // flip book makes, so it is only the fallback.
    if (typeof canvas.toBlob !== "function") {
      resolve(canvas.toDataURL("image/png"))
      return
    }
    canvas.toBlob((blob) => {
      resolve(blob ? URL.createObjectURL(blob) : canvas.toDataURL("image/png"))
    }, "image/png")
  })
}

/** Release a URL produced by `rasterizePdfPage`. Safe for data-URL fallbacks. */
export function releaseRasterUrl(src: string | undefined | null): void {
  if (!src || !src.startsWith("blob:")) return
  try {
    URL.revokeObjectURL(src)
  } catch {
    // Already revoked, or the document is being torn down.
  }
}

export async function rasterizePdfPage(input: {
  page: PdfPageProxy
  cssWidth: number
  cssHeight: number
  pixelRatio?: number
}): Promise<{ src: string; width: number; height: number }> {
  const pixelRatio = input.pixelRatio ?? (typeof window === "undefined" ? 1 : Math.max(1, window.devicePixelRatio || 1))
  const base = input.page.getViewport({ scale: 1 })
  const fit = Math.min(input.cssWidth / base.width, input.cssHeight / base.height)
  const viewport = input.page.getViewport({ scale: fit })
  const canvas = document.createElement("canvas")
  await renderPdfPageToCanvas({
    page: input.page,
    canvas,
    scale: fit,
    pixelRatio,
  }).promise
  const src = await canvasToObjectUrl(canvas)
  // Drop the backing store now that the bitmap is encoded; Safari keeps large
  // canvases alive well past the last reference otherwise.
  canvas.width = 0
  canvas.height = 0
  return {
    src,
    width: Math.floor(viewport.width),
    height: Math.floor(viewport.height),
  }
}

"use client"

import { useEffect, useRef, useState } from "react"
import {
  extractPdfPageText,
  loadPdfDocument,
  pdfPageAspectRatio,
  rasterizePdfPage,
  releaseRasterUrl,
} from "../pdf-runtime"
import type { BookPreviewError } from "../types"

export type PdfSheet = {
  id: string
  src: string
  width: number
  height: number
  /** Plain page text, when extraction is enabled. Empty for image-only pages. */
  text: string
}

type UsePdfSheetsOptions = {
  pdfUrl: string | undefined
  /** False for page-backed sources; the hook then does no work at all. */
  enabled: boolean
  /** Rasterization is reordered so the page being read paints first. */
  pageIndex: number
  rasterWidth: number
  /**
   * "uniform" sizes every sheet to page 1's aspect ratio, which is what a
   * bound book needs -- leaves cannot each be a different shape. "per-page"
   * measures each page, for continuous scrolling.
   */
  sizing: "uniform" | "per-page"
  /** Pull plain text per page so the reader can search and speak a PDF. */
  extractText?: boolean
  /**
   * Bound live rasters to +/- this many pages around the reading position.
   * Pages that fall outside are revoked and re-render on return, so a long
   * document holds ~2*windowRadius+1 decoded bitmaps instead of all of them.
   * Omit for engines that must keep every sheet painted (the curl flip book
   * owns all leaves at once).
   */
  windowRadius?: number
  onError: (error: BookPreviewError) => void
  errorMessage: string
}

type UsePdfSheetsResult = {
  sheets: PdfSheet[] | null
  /** height / width of page 1, once known. Null until the document opens. */
  ratio: number | null
  prepared: number
  preparing: boolean
}

/**
 * Opens a PDF and rasterizes its pages into image sheets.
 *
 * Every sheet is mounted up front with an empty src so the reader knows the
 * page count immediately and stays usable while pages fill in behind it.
 * Rasters are object URLs, released together when the document is torn down --
 * they cannot be released per sheet, because the curl engine clones the <img>
 * nodes into a flip book that React does not own.
 */
export function usePdfSheets({
  pdfUrl,
  enabled,
  pageIndex,
  rasterWidth,
  sizing,
  extractText = false,
  windowRadius,
  onError,
  errorMessage,
}: UsePdfSheetsOptions): UsePdfSheetsResult {
  // Sheets are keyed to the url that produced them: when pdfUrl changes the
  // stale document stops matching the gate below, so no effect-body reset is
  // needed and a superseded load can never publish its pages.
  const [doc, setDoc] = useState<{
    url: string
    ratio: number | null
    sheets: PdfSheet[] | null
  } | null>(null)
  const priorityRef = useRef(pageIndex + 1)
  const wakeRef = useRef<(() => void) | null>(null)
  const reportError = useRef(onError)
  const message = useRef(errorMessage)

  useEffect(() => {
    priorityRef.current = pageIndex + 1
    reportError.current = onError
    message.current = errorMessage
    // Resume a parked windowed drain — the new reading position may need
    // pages the loop skipped.
    wakeRef.current?.()
  })

  useEffect(() => {
    if (!enabled || !pdfUrl) return
    let cancelled = false
    let loaded: Awaited<ReturnType<typeof loadPdfDocument>> | null = null
    let uniformHeight = 0
    let pixelRatio = 1
    // Live rasters by page number; doubles as the teardown revocation list.
    const rendered = new Map<number, string>()
    // Pages already tried — attempted failures stay blank rather than
    // re-failing on every pass, matching the old once-only queue.
    const attempted = new Set<number>()

    const inWindow = (pageNumber: number, priority: number): boolean =>
      windowRadius === undefined || Math.abs(pageNumber - priority) <= windowRadius

    // Pages commit through this guarded writer. It stays a flat async
    // function — not a loop body — so each post-await state write is provably
    // dominated by a cancellation check.
    async function renderSheet(url: string, pageNumber: number): Promise<void> {
      if (cancelled || !loaded) return
      attempted.add(pageNumber)
      try {
        const page = await loaded.doc.getPage(pageNumber)
        // Text first: it is cheap, and it makes the page findable before
        // its bitmap has finished painting.
        const text = extractText ? await extractPdfPageText(page) : ""
        if (cancelled) return
        const cssHeight =
          sizing === "uniform"
            ? uniformHeight
            : Math.round(rasterWidth * pdfPageAspectRatio(page))
        const raster = await rasterizePdfPage({
          page,
          cssWidth: rasterWidth,
          cssHeight,
          pixelRatio,
        })
        if (cancelled) {
          releaseRasterUrl(raster.src)
          return
        }
        const previous = rendered.get(pageNumber)
        if (previous) releaseRasterUrl(previous)
        rendered.set(pageNumber, raster.src)
        const id = `pdf-${pageNumber}`
        setDoc(
          (current) =>
            current && current.url === url && current.sheets
              ? {
                  ...current,
                  sheets: current.sheets.map((sheet) =>
                    sheet.id === id
                      ? {
                          ...sheet,
                          src: raster.src,
                          width: raster.width,
                          height: raster.height,
                          text,
                        }
                      : sheet
                  ),
                }
              : current
        )
      } catch {
        // A single bad page stays blank instead of failing the document.
      }
    }

    // Revokes rasters that fell behind the reading position. The extracted
    // text stays — it is small — so a pruned page re-renders its bitmap only.
    function prune(url: string, priority: number): void {
      if (windowRadius === undefined) return
      for (const [pageNumber, src] of rendered) {
        if (inWindow(pageNumber, priority)) continue
        rendered.delete(pageNumber)
        attempted.delete(pageNumber)
        releaseRasterUrl(src)
        const id = `pdf-${pageNumber}`
        setDoc((current) =>
          current && current.url === url && current.sheets
            ? {
                ...current,
                sheets: current.sheets.map((sheet) =>
                  sheet.id === id ? { ...sheet, src: "" } : sheet
                ),
              }
            : current
        )
      }
    }

    // Nearest unrendered page to the reading position, expanding outward —
    // a reader at page 50 gets 50, 51, 49, 52, 48… instead of waiting for
    // everything before it.
    function pickNext(priority: number, count: number): number | undefined {
      if (!attempted.has(priority) && priority <= count) return priority
      for (let distance = 1; distance < count; distance += 1) {
        if (windowRadius !== undefined && distance > windowRadius) break
        const before = priority - distance
        const after = priority + distance
        if (before >= 1 && inWindow(before, priority) && !attempted.has(before)) {
          return before
        }
        if (after <= count && inWindow(after, priority) && !attempted.has(after)) {
          return after
        }
        if (before < 1 && after > count) break
      }
      return undefined
    }

    // One sequential worker per document. Without a window it ends when every
    // page is painted; with a window it parks when the visible range is done
    // and the priority effect above wakes it on the next page turn.
    async function drain(url: string): Promise<void> {
      const count = loaded?.doc.numPages ?? 0
      while (!cancelled && loaded) {
        const priority = Math.min(Math.max(1, priorityRef.current), count)
        prune(url, priority)
        const next = pickNext(priority, count)
        if (next === undefined) {
          if (windowRadius === undefined) return
          await new Promise<void>((resolve) => {
            wakeRef.current = resolve
          })
          wakeRef.current = null
          continue
        }
        await renderSheet(url, next)
      }
    }

    async function open(url: string) {
      try {
        const result = await loadPdfDocument(url)
        loaded = result
        if (cancelled) {
          await result.task.destroy()
          return
        }
        const count = result.doc.numPages
        // A 960px sheet at 2x is already roughly a 4MP bitmap. Capping DPR
        // avoids turning high-density phones into a large memory multiplier.
        pixelRatio =
          typeof window === "undefined" ? 1 : Math.min(2, Math.max(1, window.devicePixelRatio || 1))

        const firstPage = await result.doc.getPage(1)
        if (cancelled) return
        const baseRatio = pdfPageAspectRatio(firstPage)
        uniformHeight = Math.round(rasterWidth * baseRatio)

        setDoc({
          url,
          ratio: baseRatio,
          sheets: Array.from({ length: count }, (_, index) => ({
            id: `pdf-${index + 1}`,
            src: "",
            width: rasterWidth,
            height: uniformHeight,
            text: "",
          })),
        })

        await drain(url)
      } catch {
        if (!cancelled) {
          reportError.current({ kind: "pdf-render", message: message.current })
        }
      }
    }

    void open(pdfUrl)
    return () => {
      cancelled = true
      // Unpark the drain so it sees `cancelled` and exits.
      wakeRef.current?.()
      wakeRef.current = null
      if (loaded) void loaded.task.destroy()
      for (const src of rendered.values()) releaseRasterUrl(src)
      rendered.clear()
    }
  }, [enabled, pdfUrl, rasterWidth, sizing, extractText, windowRadius])

  const active = enabled && pdfUrl && doc?.url === pdfUrl ? doc : null
  const activeSheets = active?.sheets ?? null
  const prepared = activeSheets?.filter((sheet) => sheet.src).length ?? 0
  // With a window, "preparing" means the visible range still has gaps — far
  // pages staying blank is the intended steady state, not ongoing work.
  const pendingInWindow =
    activeSheets?.some(
      (sheet, index) =>
        !sheet.src &&
        (windowRadius === undefined ||
          Math.abs(index + 1 - (pageIndex + 1)) <= windowRadius)
    ) ?? false
  return {
    sheets: activeSheets,
    ratio: active?.ratio ?? null,
    prepared,
    preparing: enabled && activeSheets !== null && pendingInWindow,
  }
}

"use client"

import { Badge } from "@/components/ui/badge"
import { Spinner } from "@/components/ui/spinner"

/**
 * Progress while a PDF rasterizes. Uses the shared Badge primitive rather than
 * a bespoke pill so it tracks the design system automatically.
 */
export function PdfPreparingBadge({ prepared, total }: { prepared: number; total: number }) {
  return (
    <Badge
      role="status"
      variant="outline"
      data-book-preview-fade
      className="pointer-events-none absolute bottom-3 left-1/2 -translate-x-1/2 gap-1.5 bg-card/90 font-mono text-muted-foreground shadow-sm backdrop-blur"
    >
      <Spinner data-icon="inline-start" />
      {prepared}/{total}
    </Badge>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"
import { ZoomInIcon, ZoomOutIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Spinner } from "@/components/ui/spinner"
import { DEFAULT_CAPABILITIES } from "../capabilities"
import { useStableHandler } from "../hooks/use-stable-handler"
import {
  loadPdfDocument,
  renderPdfPageToCanvas,
  renderPdfTextLayer,
  type PdfDocumentProxy,
  type PdfLoadResult,
} from "../pdf-runtime"
import type { BookPreviewEngineProps } from "../types"

// A zoom of 0 is the fit-width sentinel: the real scale is derived per page
// from the live scroller width, so phones and mixed-orientation documents
// open readable instead of pre-panned.
const PDF_FIT_ZOOM = 0
const PDF_MIN_ZOOM = 0.5
const PDF_MAX_ZOOM = 4
const PDF_STAGE_PAD = 32

function clampZoom(value: number): number {
  return Math.min(PDF_MAX_ZOOM, Math.max(PDF_MIN_ZOOM, value))
}

export default function PdfEngine({
  source,
  pageIndex,
  onReady,
  onError,
}: BookPreviewEngineProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const textLayerRef = useRef<HTMLDivElement | null>(null)
  const scrollRef = useRef<HTMLDivElement | null>(null)
  const docTaskRef = useRef<PdfLoadResult["task"] | null>(null)
  const [pdf, setPdf] = useState<PdfDocumentProxy | null>(null)
  const [zoom, setZoom] = useState(PDF_FIT_ZOOM)
  const [fitted, setFitted] = useState(1)
  const [fitTick, setFitTick] = useState(0)
  const fittedRef = useRef(1)
  const zoomRef = useRef(PDF_FIT_ZOOM)
  const reportReady = useStableHandler(onReady)
  const reportError = useStableHandler(onError)

  useEffect(() => {
    zoomRef.current = zoom
  }, [zoom])

  useEffect(() => {
    let cancelled = false
    let doc: PdfDocumentProxy | null = null

    async function open() {
      if (!source.pdfUrl && !source.allowPdfUpload) {
        reportError({
          kind: "invalid-source",
          message: "Provide a PDF URL or enable uploads.",
        })
        return
      }
      if (!source.pdfUrl) {
        reportReady({
          totalPages: 0,
          capabilities: {
            ...DEFAULT_CAPABILITIES,
            upload: true,
            zoom: true,
            appearance: false,
            sound: false,
          },
        })
        return
      }
      try {
        const loaded = await loadPdfDocument(source.pdfUrl)
        if (cancelled) {
          await loaded.task.destroy()
          return
        }
        docTaskRef.current = loaded.task
        doc = loaded.doc
        setPdf(doc)
        // A new document always opens at fit-width.
        setZoom(PDF_FIT_ZOOM)
        reportReady({
          totalPages: doc.numPages,
          capabilities: {
            ...DEFAULT_CAPABILITIES,
            zoom: true,
            upload: source.allowPdfUpload,
            download: Boolean(source.downloadUrl || source.pdfUrl),
            appearance: false,
            sound: false,
          },
        })
      } catch {
        if (!cancelled) {
          reportError({ kind: "pdf-parse", message: "This PDF could not be opened." })
        }
      }
    }

    void open()
    return () => {
      cancelled = true
      void docTaskRef.current?.destroy()
      docTaskRef.current = null
      setPdf(null)
    }
  }, [reportError, reportReady, source.allowPdfUpload, source.downloadUrl, source.pdfUrl])

  // In fit mode a container resize is a zoom change.
  useEffect(() => {
    const node = scrollRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(() => {
      if (zoomRef.current === PDF_FIT_ZOOM) setFitTick((tick) => tick + 1)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  useEffect(() => {
    if (!pdf || !canvasRef.current) return
    let cancelled = false
    let renderTask: { promise: Promise<void>; cancel: () => void } | null = null
    const documentProxy = pdf
    const textLayerEl = textLayerRef.current

    let textLayer: { cancel: () => void } | null = null

    async function draw() {
      try {
        const page = await documentProxy.getPage(pageIndex + 1)
        if (cancelled || !canvasRef.current) return
        const canvas = canvasRef.current
        // The fit scale uses this page's own base size, so a landscape figure
        // inside a portrait document still reads edge to edge.
        const base = page.getViewport({ scale: 1 })
        const hostWidth = Math.max(
          240,
          (scrollRef.current?.clientWidth ?? base.width) - PDF_STAGE_PAD
        )
        const fit = Math.min(3, Math.max(0.4, hostWidth / base.width))
        fittedRef.current = fit
        setFitted(fit)
        const effective = zoom > 0 ? zoom : fit
        renderTask = renderPdfPageToCanvas({ page, canvas, scale: effective })
        await renderTask.promise
        // Selectable text belongs on the flat reader: the canvas here is
        // static, so real spans can sit exactly over it.
        const container = textLayerEl
        if (cancelled || !container) return
        container.replaceChildren()
        container.style.width = canvas.style.width
        container.style.height = canvas.style.height
        // PDF.js positions every span against this factor.
        container.style.setProperty("--total-scale-factor", String(effective))
        textLayer = await renderPdfTextLayer({ page, container, scale: effective })
      } catch (error) {
        const named = error as { name?: string }
        if (named.name !== "RenderingCancelledException" && !cancelled) {
          reportError({ kind: "pdf-render", message: "This page could not be rendered." })
        }
      }
    }

    void draw()
    return () => {
      cancelled = true
      renderTask?.cancel()
      textLayer?.cancel()
      textLayerEl?.replaceChildren()
    }
  }, [pageIndex, pdf, reportError, zoom, fitTick])

  // Ctrl+wheel (and trackpad pinch, which browsers surface as ctrl+wheel) zooms
  // the document instead of scrolling. Needs a non-passive native listener.
  useEffect(() => {
    const node = scrollRef.current
    if (!node) return
    const onWheel = (event: WheelEvent) => {
      if (!event.ctrlKey) return
      event.preventDefault()
      const current = zoomRef.current > 0 ? zoomRef.current : fittedRef.current
      setZoom(clampZoom(current - Math.sign(event.deltaY) * 0.15))
    }
    node.addEventListener("wheel", onWheel, { passive: false })
    return () => node.removeEventListener("wheel", onWheel)
  }, [])

  const effectiveZoom = zoom > 0 ? zoom : fitted

  return (
    <div className="flex h-full w-full flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center justify-center gap-2">
        <p className="text-xs text-muted-foreground">{source.pdfFileName ?? "Document"}</p>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label="Zoom out"
          onClick={() => setZoom(clampZoom(effectiveZoom - 0.25))}
          data-book-preview-press
          className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
        >
          <ZoomOutIcon />
        </Button>
        <span className="font-mono text-xs text-muted-foreground">
          {zoom === PDF_FIT_ZOOM
            ? `Fit ${Math.round(effectiveZoom * 100)}%`
            : `${Math.round(zoom * 100)}%`}
        </span>
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label="Zoom in"
          onClick={() => setZoom(clampZoom(effectiveZoom + 0.25))}
          data-book-preview-press
          className="min-h-11 min-w-11 sm:min-h-7 sm:min-w-7"
        >
          <ZoomInIcon />
        </Button>
        <Button
          type="button"
          variant={zoom === PDF_FIT_ZOOM ? "secondary" : "ghost"}
          size="sm"
          aria-pressed={zoom === PDF_FIT_ZOOM}
          aria-label="Fit page width"
          onClick={() => setZoom(PDF_FIT_ZOOM)}
          data-book-preview-press
        >
          Fit
        </Button>
      </div>
      <div
        ref={scrollRef}
        className="flex min-h-0 flex-1 overflow-auto rounded-lg border bg-muted/30 p-4"
        onDoubleClick={() =>
          setZoom((current) =>
            current === PDF_FIT_ZOOM ? clampZoom(fittedRef.current * 1.75) : PDF_FIT_ZOOM
          )
        }
      >
        {!pdf ? (
          <div className="m-auto flex items-center gap-2 text-sm text-muted-foreground">
            <Spinner />
            {source.allowPdfUpload ? "Upload or drop a PDF to begin" : "Waiting for a document"}
          </div>
        ) : (
          /* Auto margins center a page that fits and let a zoomed page scroll
             to every edge — justify-center would clip the start side. The
             canvas keeps its exact rendered size so the text layer can sit
             precisely on top. */
          <div className="relative m-auto shrink-0">
            <canvas ref={canvasRef} className="block rounded bg-background shadow" />
            <div ref={textLayerRef} className="textLayer" data-book-preview-text-layer />
          </div>
        )}
      </div>
    </div>
  )
}
